-- bio-core-lpm-synth
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status, core_principles)
VALUES ('b5d6da86-3133-570c-979d-e23ce81905ad', '28997544-0d87-4b05-9ee2-7c474513c108', 'concept', 'Heritable Variation', 'Individuals in a population differ in their traits, and some of those differences pass from parents to offspring. New variants arise by mutation.', NULL, '{"definition":"Individuals in a population differ in their traits, and some of those differences pass from parents to offspring. New variants arise by mutation.","vocabulary":"BIO-CORE-v1.0.0","conceptbase_id":"OE-CONCEPT-bio-core-oc-heritable-variation","level":"organizing","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":["Any account in which organisms make the variants they need."],"counterpart_in_partner_space":"Shared in part with the Interdisciplinary organizing concept The Evolutionary Pattern, which joins variation and inheritance to selection and transmission across domains.","grounding":"AI-drafted on 2026-10-25 from the stage links in content.concepts, by the rule in the design note. No subject-matter expert has reviewed it."}'::jsonb, 'proposed', '["Every population contains variation.","Only differences that are inherited can change a population over generations.","Mutation adds new variants, and no process aims at which variants appear."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status, core_principles)
VALUES ('2f175441-2308-5e92-82bb-19435535b5ff', '28997544-0d87-4b05-9ee2-7c474513c108', 'concept', 'Differential Reproduction', 'Variants leave different numbers of offspring because of how they interact with their surroundings. Over generations this changes which variants are common.', NULL, '{"definition":"Variants leave different numbers of offspring because of how they interact with their surroundings. Over generations this changes which variants are common.","vocabulary":"BIO-CORE-v1.0.0","conceptbase_id":"OE-CONCEPT-bio-core-oc-differential-reproduction","level":"organizing","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":["Organisms trying, wanting or needing to change."],"counterpart_in_partner_space":"Divergent. Interdisciplinary holds the biological form as one facet of Selection, next to cultural, educational and computational forms.","grounding":"AI-drafted on 2026-10-25 from the stage links in content.concepts, by the rule in the design note. No subject-matter expert has reviewed it."}'::jsonb, 'proposed', '["Some variants leave more offspring than others in a given setting.","The same variant can do better in one setting and worse in another.","Natural settings, mating success and human breeding all act as conditions on variants. The variants do not choose the condition."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status, core_principles)
VALUES ('c3323f8c-f259-5284-bff8-f1a87d3a77c0', '28997544-0d87-4b05-9ee2-7c474513c108', 'concept', 'Change in Populations', 'The mix of variants in a population shifts from one generation to the next. Selection shifts it in a direction. Chance shifts it with no direction.', NULL, '{"definition":"The mix of variants in a population shifts from one generation to the next. Selection shifts it in a direction. Chance shifts it with no direction.","vocabulary":"BIO-CORE-v1.0.0","conceptbase_id":"OE-CONCEPT-bio-core-oc-change-in-populations","level":"organizing","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":["Change inside one individual during its lifetime."],"counterpart_in_partner_space":"Absent as a separate organizing concept in Interdisciplinary, where population-level change sits inside The Evolutionary Pattern.","grounding":"AI-drafted on 2026-10-25 from the stage links in content.concepts, by the rule in the design note. No subject-matter expert has reviewed it."}'::jsonb, 'proposed', '["The unit that changes in evolution is the population.","Selection gives change a direction and drift gives it none.","Chance effects are stronger in small populations."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status, core_principles)
VALUES ('715c1d7d-15c2-5612-aba3-6e73dba10546', '28997544-0d87-4b05-9ee2-7c474513c108', 'concept', 'Common Descent and Deep Time', 'All living things share ancestors. The history of life is a branching tree over very long time, and many branches end in extinction.', NULL, '{"definition":"All living things share ancestors. The history of life is a branching tree over very long time, and many branches end in extinction.","vocabulary":"BIO-CORE-v1.0.0","conceptbase_id":"OE-CONCEPT-bio-core-oc-common-descent","level":"organizing","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":["Ladders of progress and any main line toward one group."],"counterpart_in_partner_space":"Absent in Interdisciplinary, which has no phylogeny or extinction concept.","grounding":"AI-drafted on 2026-10-25 from the stage links in content.concepts, by the rule in the design note. No subject-matter expert has reviewed it."}'::jsonb, 'proposed', '["Relatedness is a matter of how recently two groups share an ancestor.","Lineages split, and some end.","The time involved is far longer than human history."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status, core_principles)
VALUES ('b1625166-3343-55a9-b799-10b6cdbfdb6c', '28997544-0d87-4b05-9ee2-7c474513c108', 'concept', 'Species and Divergence', 'Populations that stay apart can change in different ways until they become separate species.', NULL, '{"definition":"Populations that stay apart can change in different ways until they become separate species.","vocabulary":"BIO-CORE-v1.0.0","conceptbase_id":"OE-CONCEPT-bio-core-oc-species-divergence","level":"organizing","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":["Species as fixed types."],"counterpart_in_partner_space":"Absent in Interdisciplinary.","grounding":"AI-drafted on 2026-10-25 from the stage links in content.concepts, by the rule in the design note. No subject-matter expert has reviewed it."}'::jsonb, 'proposed', '["A species is a group of populations that can interbreed and that stay apart from other such groups.","Separation, variation and selection together produce divergence.","Large differences in appearance do not by themselves make separate species."]'::jsonb) ON CONFLICT (id) DO NOTHING;

