-- interdisciplinary-lpm-synth
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status, core_principles)
VALUES ('ab896065-5feb-5fb9-ad34-a8599ddf6049', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'The Evolutionary Pattern', 'Variants appear, some persist or spread more than others, and traits or practices pass on. The same pattern appears in living things, culture, learning and technology. Each domain gives the key words its own meaning, so students learn the pattern and its differences.', NULL, '{"definition":"Variants appear, some persist or spread more than others, and traits or practices pass on. The same pattern appears in living things, culture, learning and technology. Each domain gives the key words its own meaning, so students learn the pattern and its differences.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-oc-evolutionary-pattern","level":"organizing","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":["Treating the pattern as proof that the domains work in the same way."],"counterpart_in_partner_space":"Shared in part with Bio-Core. Bio-Core splits the pattern into Heritable Variation, Differential Reproduction and Change in Populations and keeps each in biology only.","grounding":"AI-drafted on 2026-10-25 from the stage links in content.concepts, by the rule in the design note. No subject-matter expert has reviewed it."}'::jsonb, 'proposed', '["Variation, selection and transmission together make a general pattern.","Selection, inheritance and transmission carry a domain-specific meaning in biology, culture, education and computing.","Using the pattern on a new case means checking which parts carry over."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status, core_principles)
VALUES ('5251f868-4d6f-56fd-91df-5791d2efbcd1', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Agency and Niche Construction', 'Individuals and groups act, and their actions change the conditions that selection works on. The space teaches when thinking in terms of goals and choices explains something and when it misleads.', NULL, '{"definition":"Individuals and groups act, and their actions change the conditions that selection works on. The space teaches when thinking in terms of goals and choices explains something and when it misleads.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-oc-agency-niche","level":"organizing","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":["Agency used everywhere, and agency left out everywhere."],"counterpart_in_partner_space":"Absent in Bio-Core by design, whose vocabulary has no organism agency.","grounding":"AI-drafted on 2026-10-25 from the stage links in content.concepts, by the rule in the design note. No subject-matter expert has reviewed it."}'::jsonb, 'proposed', '["Agency is a matter of degree and differs between organisms, people and systems.","What an actor does can change the selective setting for itself and for others.","Development shapes what an actor can do."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status, core_principles)
VALUES ('938e144b-1e6a-5027-8292-f19fc111d640', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Learning, Minds and Discovery', 'How individuals build, test and pass on understanding, with support from others, and how minds search for better ideas by starting from similar cases.', NULL, '{"definition":"How individuals build, test and pass on understanding, with support from others, and how minds search for better ideas by starting from similar cases.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-oc-learning-discovery","level":"organizing","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":["Learning described as filling an empty mind."],"counterpart_in_partner_space":"Absent in Bio-Core.","grounding":"AI-drafted on 2026-10-25 from the stage links in content.concepts, by the rule in the design note. No subject-matter expert has reviewed it."}'::jsonb, 'proposed', '["Learning builds on what a learner already believes.","Support from others is temporary and is withdrawn as competence grows.","Comparing a new case with a familiar one is a way to search for ideas, and the comparison needs checking."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status, core_principles)
VALUES ('7c3323f6-9afd-54ba-a6ba-0f6b09ced583', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Culture and Social Structure', 'Groups share and carry knowledge and practices. Norms and institutions regulate behavior, and groups meet shared problems through cooperation and conflict.', NULL, '{"definition":"Groups share and carry knowledge and practices. Norms and institutions regulate behavior, and groups meet shared problems through cooperation and conflict.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-oc-culture-social","level":"organizing","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":["Culture as a fixed list of traits of a group of people."],"counterpart_in_partner_space":"Absent in Bio-Core.","grounding":"AI-drafted on 2026-10-25 from the stage links in content.concepts, by the rule in the design note. No subject-matter expert has reviewed it."}'::jsonb, 'proposed', '["Culture persists beyond any one member of a group.","Norms and institutions stabilize group behavior.","Cooperation and conflict both shape which practices spread."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status, core_principles)
VALUES ('c9290170-3f1d-5e74-8a4d-3864d2ca6a18', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Information, Technology and Collective Systems', 'Information is encoded, communicated and represented. Tools and distributed systems extend what individuals can do, alone and together.', NULL, '{"definition":"Information is encoded, communicated and represented. Tools and distributed systems extend what individuals can do, alone and together.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-oc-information-technology","level":"organizing","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":["Technology as a neutral object or as a separate force acting on people."],"counterpart_in_partner_space":"Absent in Bio-Core.","grounding":"AI-drafted on 2026-10-25 from the stage links in content.concepts, by the rule in the design note. No subject-matter expert has reviewed it."}'::jsonb, 'proposed', '["Information can be carried by genes, speech, symbols and code.","Representations stand for things and can be shared.","Tools and collective systems change what a group can know and do."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('feced49d-4653-5cb0-9ae9-9732432966fd', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Selection (biology)', 'Differential reproductive success among heritable variants.', '0573db35-8451-5189-998c-8619ea1d26ec', '{"definition":"Differential reproductive success among heritable variants.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-selection-biology","level":"discipline-facet","facet_of":"Selection","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"Taken from the discipline-specific definitions already inside the Selection concept. AI-drafted on 2026-10-25 from the stage links in content.concepts, by the rule in the design note. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('fce16fc9-478f-522f-a678-4142663f9b58', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Selection (culture)', 'Differential persistence or spread of cultural variants based on their fit to a social or environmental context.', '0573db35-8451-5189-998c-8619ea1d26ec', '{"definition":"Differential persistence or spread of cultural variants based on their fit to a social or environmental context.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-selection-culture","level":"discipline-facet","facet_of":"Selection","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"Taken from the discipline-specific definitions already inside the Selection concept. AI-drafted on 2026-10-25 from the stage links in content.concepts, by the rule in the design note. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('058f6b81-69af-50c6-91a9-6e236a37bc50', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Selection (education)', 'Choosing among available instructional pathways or resources.', '0573db35-8451-5189-998c-8619ea1d26ec', '{"definition":"Choosing among available instructional pathways or resources.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-selection-education","level":"discipline-facet","facet_of":"Selection","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"Taken from the discipline-specific definitions already inside the Selection concept. AI-drafted on 2026-10-25 from the stage links in content.concepts, by the rule in the design note. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('b836c9a1-8b9d-58b6-af8c-009fc93c0603', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Selection (AI and computation)', 'A search or optimization process that favors candidates scoring higher against an objective function.', '0573db35-8451-5189-998c-8619ea1d26ec', '{"definition":"A search or optimization process that favors candidates scoring higher against an objective function.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-selection-ai","level":"discipline-facet","facet_of":"Selection","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"Taken from the discipline-specific definitions already inside the Selection concept. AI-drafted on 2026-10-25 from the stage links in content.concepts, by the rule in the design note. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
